;			// msg-data			msgNum->AddSubTerm(fetch);			msgNum->AddSubTerm(paren);				// msg-att				paren->AddSubTerm(bodyTerm);					bodyTerm->AddSubTerm(bodySectTerm);			// section						bodySectTerm->AddSubTerm(bodyBrktTerm);		// sect-spec							bodyBrktTerm->AddSubTerm(bodySection);	// sect-msgtext								bodySection->AddSubTerm(sectMsgText1);							bodyBrktTerm->AddSubTerm(plc5Term);		// sect-part								plc5Term->AddSubTerm(plc6Term);									plc6Term->AddSubTerm(integer1);									plc6Term->AddSubTerm(plc7Term);										plc7Term->AddSubTerm(period1);										plc7Term->AddSubTerm(integer2);								plc5Term->AddSubTerm(period2);			// sect-text						bodySectTerm->AddSubTerm(plc8Term);							plc8Term->AddSubTerm(sectionString);				paren->AddSubTerm(msgUIDTerm);					msgUIDTerm->AddSubTerm(uidID);		starTerm->AddSubTerm(rol1Term);	this->AddSubTerm(stdsTerm);	this->AddSubTerm(cmdtTerm);	this->AddSubTerm(rol2Term);}//----------------------------------------------------------------------------------------// CFetchBodyTextParse::ParseFetchStream//----------------------------------------------------------------------------------------CFetchResponseToken* CFetchBodyTextParse::ParseFetchStream()// Set up and execute our FETCH (BODY[TEXT]) parse tree.{	// •••  This command should not receive a response consisting	// of "FETCH (BODY[1])" but it does from an AppleShare IP server.	// Create our master token.	CAutoPtr_AC<CFetchResponseToken> 	apParseToken(TH_new CFetchResponseToken(this));	Reset();		// Reset ourselves.	MakeSubTerms();	// Parse the response.	bool success = ParseStream(apParseToken);	return apParseToken.release();}//========================================================================================// CFetchEnvelopeParse//========================================================================================//----------------------------------------------------------------------------------------// CFetchEnvelopePars